// Some portions generated by Claude Code

// Stored query results, as the Workbench keeps them (queryStream.ts): a result past 10,000 rows moves to an IndexedDB
// database of its own, named DATABASE_PREFIX + its id and listed in a localStorage registry; smaller results stay in
// the page's memory.

const DATABASE_PREFIX = 'rdf4j-workbench-row-store:';
const REGISTRY_PREFIX = 'rdf4j.workbench.row-store.v2:';
const MAINTAINED_KEY = 'rdf4j.workbench.row-store.v2.maintained';

/** A query of rows × columns rows that needs no data: enough rows to be stored in IndexedDB. */
function largeQuery(rows = 120, columns = 100) {
	const range = (count) => Array.from({ length: count }, (_, index) => String(index)).join(' ');
	return `SELECT ?a ?b WHERE { VALUES ?a { ${range(rows)} } VALUES ?b { ${range(columns)} } }`;
}

/** The ids of the stored results with a database, and the registry entries, of the page's origin. */
async function storedResults(page) {
	return page.evaluate(async ({ databasePrefix, registryPrefix }) => {
		// A version-0 entry is what an aborted open leaves in WebKit: no store.
		const databases = (await indexedDB.databases())
			.filter((database) => database.version > 0 && database.name && database.name.startsWith(databasePrefix))
			.map((database) => database.name.substring(databasePrefix.length)).sort();
		const registry = {};
		for (let index = 0; index < localStorage.length; index++) {
			const key = localStorage.key(index);
			if (key && key.startsWith(registryPrefix)) {
				registry[key.substring(registryPrefix.length)] = JSON.parse(localStorage.getItem(key));
			}
		}
		return { databases, registry };
	}, { databasePrefix: DATABASE_PREFIX, registryPrefix: REGISTRY_PREFIX });
}

/** Makes the registry say the stores were created and last used at time. */
async function ageStoredResults(page, ids, time) {
	await page.evaluate(({ registryPrefix, ids, time }) => {
		for (const id of ids) {
			const entry = JSON.parse(localStorage.getItem(registryPrefix + id));
			localStorage.setItem(registryPrefix + id, JSON.stringify(Object.assign(entry, { created: time, used: time })));
		}
	}, { registryPrefix: REGISTRY_PREFIX, ids, time });
}

/** A stored result left by a page that ended without disposing it: its database and its registry entry. */
async function plantAbandonedStore(page, id, time) {
	await page.evaluate(({ databasePrefix, registryPrefix, id, time }) => new Promise((resolve, reject) => {
		const request = indexedDB.open(databasePrefix + id, 1);
		request.onupgradeneeded = () => {
			request.result.createObjectStore('stores', { keyPath: 'id' });
			request.result.createObjectStore('rows', { keyPath: ['storeId', 'index'] });
		};
		request.onerror = () => reject(request.error);
		request.onsuccess = () => {
			const database = request.result;
			const transaction = database.transaction(['stores', 'rows'], 'readwrite');
			transaction.objectStore('stores').put({ id, count: 1, format: 'blocks-v2', tailStart: 0, tailRows: 1,
				tailChars: 6, touched: time });
			transaction.objectStore('rows').put({ storeId: id, index: 0, count: 1, text: '[null]' });
			transaction.oncomplete = () => {
				database.close();
				localStorage.setItem(registryPrefix + id, JSON.stringify({ created: time, used: time, bytes: 20 }));
				resolve();
			};
			transaction.onerror = () => reject(transaction.error);
		};
	}), { databasePrefix: DATABASE_PREFIX, registryPrefix: REGISTRY_PREFIX, id, time });
}

/** Lets the next cleanup look at every store, not only those flagged for deletion. */
async function forgetLastCleanup(page) {
	await page.evaluate((key) => localStorage.removeItem(key), MAINTAINED_KEY);
}

module.exports = { DATABASE_PREFIX, REGISTRY_PREFIX, largeQuery, storedResults, ageStoredResults, plantAbandonedStore,
	forgetLastCleanup };
